CREATE OR ALTER PROCEDURE [dbo].[uspStorageZone_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @WarehouseId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[WarehouseId]
			, t.[Code]
			, t.[Name]
			, t.[TemperatureMin]
			, t.[TemperatureMax]
			, t.[Status]
			, t.[TemperatureRange]
			, t.[CreatedDate]
		FROM [dbo].[StorageZone] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%'))
			AND (@WarehouseId IS NULL OR t.[WarehouseId] = @WarehouseId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'temperatureMin' THEN r.[TemperatureMin] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'temperatureMin' THEN r.[TemperatureMin] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'temperatureMax' THEN r.[TemperatureMax] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'temperatureMax' THEN r.[TemperatureMax] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'temperatureRange' THEN r.[TemperatureRange] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'temperatureRange' THEN r.[TemperatureRange] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
